const locationMap = {
  '1': 'PLACEHOLDER_GHL_1',
  '2': 'PLACEHOLDER_GHL_2',
  '3': 'PLACEHOLDER_GHL_3',
  '4': 'PLACEHOLDER_GHL_4',
  '5': 'PLACEHOLDER_GHL_5',
  '6': 'PLACEHOLDER_GHL_6',
  '7': 'PLACEHOLDER_GHL_7',
  '8': 'PLACEHOLDER_GHL_8',
  '9': 'PLACEHOLDER_GHL_9',
  '10': 'PLACEHOLDER_GHL_10',
  '11': 'PLACEHOLDER_GHL_11',
  '12': 'PLACEHOLDER_GHL_12',
  '13': 'PLACEHOLDER_GHL_13',
  '14': 'PLACEHOLDER_GHL_14',
  '15': 'PLACEHOLDER_GHL_15'
};

const body = $input.first().json.body || {};
const clientId = body.clientId;

if (!clientId) {
  return [{ json: { success: false, error: 'INVALID_CLIENT_ID', message: 'clientId is required' } }];
}

const locationId = locationMap[clientId];
if (!locationId) {
  return [{ json: { success: false, error: 'INVALID_CLIENT_ID', message: 'Client ID not found in GHL mapping' } }];
}

return [{ json: { clientId, locationId } }];

const clientId = $('Resolve Location').first().json.clientId;
const oppsResponse = $('Get Opportunities').first().json;
const contactsResponse = $('Get Recent Contacts').first().json;

const opportunities = oppsResponse.body?.opportunities || oppsResponse.opportunities || [];
const contacts = contactsResponse.body?.contacts || contactsResponse.contacts || [];

// Count leads per stage
const stages = {
  'New Lead': 0,
  'Conversation': 0,
  'Appointment Set': 0,
  'Application': 0,
  'Closed Won': 0
};

opportunities.forEach(opp => {
  const stageName = opp.pipelineStageId || opp.status || 'New Lead';
  // Map GHL stage names to our standard stages
  if (stageName.toLowerCase().includes('new') || stageName.toLowerCase().includes('lead')) stages['New Lead']++;
  else if (stageName.toLowerCase().includes('conversation') || stageName.toLowerCase().includes('contact')) stages['Conversation']++;
  else if (stageName.toLowerCase().includes('appointment') || stageName.toLowerCase().includes('booked')) stages['Appointment Set']++;
  else if (stageName.toLowerCase().includes('application') || stageName.toLowerCase().includes('app')) stages['Application']++;
  else if (stageName.toLowerCase().includes('closed') || stageName.toLowerCase().includes('won')) stages['Closed Won']++;
  else stages['New Lead']++;
});

// Calculate conversion rates
const conversionRates = {
  leadToConversation: stages['New Lead'] > 0 ? parseFloat((stages['Conversation'] / stages['New Lead'] * 100).toFixed(1)) : 0,
  conversationToAppt: stages['Conversation'] > 0 ? parseFloat((stages['Appointment Set'] / stages['Conversation'] * 100).toFixed(1)) : 0,
  apptToApplication: stages['Appointment Set'] > 0 ? parseFloat((stages['Application'] / stages['Appointment Set'] * 100).toFixed(1)) : 0,
  applicationToClose: stages['Application'] > 0 ? parseFloat((stages['Closed Won'] / stages['Application'] * 100).toFixed(1)) : 0
};

// Format recent leads
const recentLeads = contacts.slice(0, 10).map(c => ({
  name: [c.firstName, c.lastName].filter(Boolean).join(' ') || 'Unknown',
  email: c.email || '',
  phone: c.phone || '',
  dateAdded: c.dateAdded || '',
  tags: c.tags || []
}));

return [{
  json: {
    success: true,
    clientId,
    pipeline: {
      stages: Object.entries(stages).map(([name, count]) => ({ name, count })),
      conversionRates,
      recentLeads,
      totalOpportunities: opportunities.length
    }
  }
}];
